"use client";

import { notFound } from 'next/navigation';
import { DashboardShell } from '@/components/dashboard-shell';

const sections: Record<string, { title: string; description: string }> = {
  profile: { title: 'Profile', description: 'Keep your contact information and preferences up to date.' },
  orders: { title: 'Order history', description: 'Review active and completed purchases in one place.' },
  wishlist: { title: 'Wishlist', description: 'Save favorites for later and revisit them anytime.' },
  addresses: { title: 'Addresses', description: 'Manage delivery locations for faster checkout.' },
  notifications: { title: 'Notifications', description: 'Choose how you want to hear from BIN DAUD.' },
  payments: { title: 'Payments', description: 'Keep preferred payment methods and billing details handy.' },
  settings: { title: 'Settings', description: 'Adjust the app experience to match your preferences.' },
  security: { title: 'Security', description: 'Manage your password and account access.' },
};

export default function DashboardSectionPage({ params }: { params: { section: string } }) {
  const section = sections[params.section];
  if (!section) {
    notFound();
  }

  return (
    <DashboardShell>
      <div className="rounded-2xl border border-slate-800 bg-slate-900/70 p-6">
        <p className="text-sm uppercase tracking-[0.3em] text-cyan-400">{params.section}</p>
        <h2 className="mt-2 text-2xl font-semibold">{section.title}</h2>
        <p className="mt-2 text-sm text-slate-400">{section.description}</p>
        <div className="mt-6 rounded-2xl border border-slate-800 bg-slate-950/70 p-6 text-sm text-slate-300">
          This section is ready for the next layer of account-specific UI and data wiring.
        </div>
      </div>
    </DashboardShell>
  );
}
