"use client";

import { useEffect, type ReactNode } from 'react';
import Link from 'next/link';
import { useAuth } from '@/lib/auth-context';
import { usePathname, useRouter } from 'next/navigation';

const links = [
  { href: '/dashboard', label: 'Dashboard' },
  { href: '/dashboard/profile', label: 'Profile' },
  { href: '/dashboard/orders', label: 'Order History' },
  { href: '/dashboard/wishlist', label: 'Wishlist' },
  { href: '/dashboard/addresses', label: 'Addresses' },
  { href: '/dashboard/notifications', label: 'Notifications' },
  { href: '/dashboard/payments', label: 'Payments' },
  { href: '/dashboard/settings', label: 'Settings' },
  { href: '/dashboard/security', label: 'Security' },
];

export function DashboardShell({ children }: { children: ReactNode }) {
  const pathname = usePathname();
  const router = useRouter();
  const { signOut, user, loading } = useAuth();

  useEffect(() => {
    if (!loading && !user) {
      router.replace('/auth/login');
    }
  }, [loading, router, user]);

  if (loading || !user) {
    return <div className="min-h-screen bg-slate-950 p-8 text-slate-300">Loading your account…</div>;
  }

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100">
      <header className="border-b border-slate-800 bg-slate-900/80">
        <div className="mx-auto flex max-w-7xl items-center justify-between px-4 py-4 sm:px-6 lg:px-8">
          <div>
            <p className="text-sm uppercase tracking-[0.3em] text-cyan-400">BIN DAUD</p>
            <h1 className="text-xl font-semibold">Customer portal</h1>
          </div>
          <div className="flex items-center gap-3">
            <Link href="/cart" className="rounded-full border border-slate-700 px-4 py-2 text-sm">Cart</Link>
            <button
              onClick={() => void signOut()}
              className="rounded-full bg-cyan-500 px-4 py-2 text-sm font-medium text-slate-950 transition hover:bg-cyan-400"
            >
              Logout
            </button>
          </div>
        </div>
      </header>

      <div className="mx-auto grid max-w-7xl gap-6 px-4 py-8 sm:px-6 lg:grid-cols-[220px_minmax(0,1fr)] lg:px-8">
        <nav className="rounded-2xl border border-slate-800 bg-slate-900/70 p-4">
          <ul className="space-y-2">
            {links.map((link) => {
              const active = pathname === link.href;
              return (
                <li key={link.href}>
                  <Link
                    href={link.href}
                    className={`block rounded-xl px-3 py-2 text-sm transition ${active ? 'bg-cyan-500/15 text-cyan-300' : 'text-slate-300 hover:bg-slate-800'}`}
                  >
                    {link.label}
                  </Link>
                </li>
              );
            })}
          </ul>
        </nav>
        <div>{children}</div>
      </div>
    </div>
  );
}
